#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    // The original program expects exactly two arguments: shift and text.
    // If the number of arguments is insufficient, or any validation fails,
    // it prints "USAGE" followed by a newline (via puts).
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    // Validate the shift argument: optional leading '+' or '-', then at least one digit.
    const char *shift_str = argv[1];
    const char *p = shift_str;
    if (*p == '+' || *p == '-') {
        p++;
    }
    if (*p == '\0') {
        puts("USAGE");
        return 0;
    }
    for (; *p; ++p) {
        if (!isdigit((unsigned char)*p)) {
            puts("USAGE");
            return 0;
        }
    }

    // Convert shift to a long and reduce it modulo 26 (the Caesar cipher alphabet size).
    long shift = strtol(shift_str, NULL, 10);
    int mod = (int)(shift % 26);
    if (mod < 0) {
        mod += 26; // make it positive, matching the original's handling.
    }

    // Retrieve the text to encode.
    const char *text = argv[2];
    size_t len = strlen(text);
    // The original program limits the input length to 0x400 (1024) characters.
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }

    // Perform the Caesar shift, preserving non‑alphabetic characters.
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + mod) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + mod) % 26 + 'a';
        }
        putchar(c);
    }
    // The original program prints a trailing newline after the transformed text.
    putchar('\n');
    return 0;
}
